const D={up:[0,1],down:[0,-1],left:[-1,0],right:[1,0]};
const G=[2,2];
const dist=s=>Math.abs(G[0]-s.c)+Math.abs(G[1]-s.r);
export function initialState(){return {c:0,r:0,moves:0,hint:false,msg:''};}
export function reduce({state,event}){
if(event.type!=='action')return state;
const s=state,won=dist(s)===0;
if(event.action==='hint'){if(won)return s;return {...s,hint:true,msg:''};}
const d=D[event.action];if(!d)return s;
if(won)return {...s,msg:'Already at the goal. Press Reset to play again.'};
const c=s.c+d[0],r=s.r+d[1];
if(c<0||c>2||r<0||r>2)return {...s,msg:'That move would leave the board.',hint:false};
return {c,r,moves:s.moves+1,hint:false,msg:''};}
const X=i=>(i-1)*1.1,Z=j=>(1-j)*1.1;
export function evaluate({state}){
const s=state||initialState();const k=dist(s),won=k===0;
const x=X(s.c),z=Z(s.r);
let q=[0,0,-0.7071068,0.7071068];if(s.c>=G[0])q=[-0.7071068,0,0,0.7071068];
const msg=won?'You reached the goal in '+s.moves+' moves. Shortest possible: 4.'+(s.moves===4?' Perfect!':''):(s.msg||(s.hint?'Hint: follow the orange arrow.':'Reach the green goal square.'));
return {nodes:{token:{position:[x,won?0.44:0.38,z]},arrow:{visible:s.hint&&!won,position:[x,0.4,z],quaternion:q}},readouts:{moves:s.moves,dist:k},goal:{status:won?'won':'playing',message:msg}};}
